"""Compare optimization modes on circuits generated by ``ideation.py``."""

import argparse

import cirq

from ideation import (
    create_dicke_state,
)
from modular_optimizations import (
    apply_threshold_dd,
    cancel_adjacent_czs,
)
from vqm_simulator_harness import (
    VQMSimulatorHarness,
    generate_seeded_error_maps,
)


# ==============================================================================
# VQM simulator and scoring evaluator
# ==============================================================================


class VQMBenchmarkEvaluator:
    """Evaluate optimization modes on the validated generated circuit."""

    def __init__(
        self,
        idle_phase_error: float = 0.0,
        simulator_backend: str = "auto",
        error_seed: int = 2026,
    ) -> None:
        (
            self.sq_errors,
            self.cz_errors,
            self.zero_errors,
            self.one_errors,
        ) = generate_seeded_error_maps(error_seed)
        self.harness = VQMSimulatorHarness(
            sq_errors=self.sq_errors,
            cz_errors=self.cz_errors,
            zero_errors=self.zero_errors,
            one_errors=self.one_errors,
            idle_phase_error=idle_phase_error,
            simulator_backend=simulator_backend,
        )
        self._base_circuits: dict[
            tuple[int, int],
            tuple[cirq.Circuit, set[cirq.GridQubit]],
        ] = {}

    def _get_generated_circuit(
        self,
        num_qubits: int,
        num_excitations: int,
    ) -> tuple[cirq.Circuit, set[cirq.GridQubit]]:
        """Return the cached circuit generated by ideation.create_dicke_state."""
        key = (num_qubits, num_excitations)
        if key not in self._base_circuits:
            self._base_circuits[key] = create_dicke_state(
                num_qubits=num_qubits,
                num_excitations=num_excitations,
                cz_pauli_error_rate=self.cz_errors,
                sq_pauli_error_rate=self.sq_errors,
                zero_errors=self.zero_errors,
                one_errors=self.one_errors,
            )
        return self._base_circuits[key]

    def evaluate(
        self,
        num_qubits: int,
        num_excitations: int,
        mode: str,
        repetitions: int = 10_000,
        seed: int = 12345,
    ) -> dict[str, float | int | str]:
        """Optimize and noisily sample one generated circuit."""
        base_circuit, qubit_set = self._get_generated_circuit(
            num_qubits,
            num_excitations,
        )
        if mode == "raw_baseline":
            circuit = base_circuit.copy()
        elif mode == "baseline_adjacent":
            circuit = cancel_adjacent_czs(base_circuit)
        elif mode == "baseline_threshold":
            circuit = apply_threshold_dd(
                base_circuit,
                qubit_set,
                min_gap_moments=8,
            )
        elif mode == "baseline_adjacent_threshold":
            circuit = apply_threshold_dd(
                cancel_adjacent_czs(base_circuit),
                qubit_set,
                min_gap_moments=8,
            )
        else:
            raise ValueError(f"Unknown optimization mode: {mode!r}")

        num_moments = len(circuit.moments)
        num_czs = sum(
            1
            for moment in circuit
            for operation in moment
            if operation.gate == cirq.CZ
            and len(operation.qubits) == 2
        )

        noisy_result = self.harness.evaluate_solution(
            lambda **_: (circuit, qubit_set),
            num_qubits=num_qubits,
            num_excitations=num_excitations,
            shots=repetitions,
            seed=seed,
        )

        return {
            "mode": mode,
            "moments": num_moments,
            "cz_count": num_czs,
            "subspace_pct": (
                float(noisy_result["subspace_retention"]) * 100.0
            ),
            "score_z": float(noisy_result["score_z"]),
            "score_x": float(noisy_result["score_x"]),
            "overall_score": float(noisy_result["overall_score"]),
        }


# ==============================================================================
# Main benchmark runner
# ==============================================================================


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--shots",
        type=int,
        default=100,
        help="Shots per basis and optimization mode (use 10000 for a full run)",
    )
    parser.add_argument("--seed", type=int, default=12345)
    parser.add_argument("--error-seed", type=int, default=2026)
    parser.add_argument(
        "--idle-phase-error",
        type=float,
        default=0.0,
        help="Optional phase damping per idle logical moment",
    )
    parser.add_argument(
        "--backend",
        choices=("auto", "density_matrix", "trajectory"),
        default="auto",
    )
    arguments = parser.parse_args()

    evaluator = VQMBenchmarkEvaluator(
        idle_phase_error=arguments.idle_phase_error,
        simulator_backend=arguments.backend,
        error_seed=arguments.error_seed,
    )
    test_cases = [(4, 2), (5, 2), (6, 3)]
    modes = [
        "raw_baseline",
        "baseline_adjacent",
        "baseline_threshold",
        "baseline_adjacent_threshold",
    ]
    score_totals = {mode: 0.0 for mode in modes}

    for num_qubits, num_excitations in test_cases:
        print(
            "\n=== Benchmark for Dicke State "
            f"|D_{num_qubits}^{num_excitations}> ==="
        )
        print(
            f"{'Mode':<30} | {'Moments':<7} | {'CZs':<5} | "
            f"{'Subspace %':<10} | {'Judge Score':<13}"
        )
        print("-" * 75)

        for mode in modes:
            result = evaluator.evaluate(
                num_qubits,
                num_excitations,
                mode=mode,
                repetitions=arguments.shots,
                seed=arguments.seed,
            )
            score_totals[mode] += float(result["overall_score"])
            print(
                f"{result['mode']:<30} | "
                f"{result['moments']:<7} | "
                f"{result['cz_count']:<5} | "
                f"{result['subspace_pct']:>9.2f}% | "
                f"{result['overall_score']:>13.4f}"
            )

    print("\n=== Estimated Judge-Score Totals for Listed Cases ===")
    for mode in modes:
        print(f"{mode:<30}: {score_totals[mode]:.6f}")
